const t=k=>text[prefs.lang][k]||k, date=n=>new Intl.DateTimeFormat(prefs.lang==='ar'?'ar-SA-u-ca-gregory':'en-GB',{day:'numeric',month:'short'}).format(new Date(n));
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4300)}
function persistPrefs(){try{localStorage.setItem('appnote-prefs',JSON.stringify(prefs))}catch{}document.documentElement.lang=prefs.lang;document.documentElement.dir=prefs.lang==='ar'?'rtl':'ltr';document.body.classList.toggle('dark',prefs.theme==='dark');}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('appnote',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspaces');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function storeGet(key){return new Promise((resolve,reject)=>{const r=db.transaction('workspaces').objectStore('workspaces').get(key);r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function storePut(key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('workspaces','readwrite');tx.objectStore('workspaces').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
const workspace=()=>session?.user.id||'guest';
let saveChain=Promise.resolve();
function saveLocal(){const key=workspace(),snapshot=structuredClone(records);saveChain=saveChain.catch(()=>{}).then(()=>storePut(key,snapshot));saveChain.then(()=>{const el=$('#saved');if(el)el.textContent=t('saved')}).catch(()=>{toast(t('storageError'));const el=$('#saved');if(el)el.textContent=t('unsaved')});return saveChain;}
function change(r){r.updated=Date.now();r.dirty=true;const el=$('#saved');if(el)el.textContent=t('saving');saveLocal();clearTimeout(syncTimer);syncTimer=setTimeout(sync,1300);}
function make(kind,data){const r={id:uid(),kind,data,updated:Date.now(),rev:0,dirty:true,deleted:false};records.unshift(r);change(r);return r;}
function sanitize(html){const doc=new DOMParser().parseFromString(String(html),'text/html');const allowed=new Set(['P','DIV','BR','SPAN','B','STRONG','I','EM','U','S','STRIKE','UL','OL','LI','H1','H2','H3','BLOCKQUOTE','IMG','INPUT','A','PRE','CODE']);function clean(node){if(node.nodeType===3)return document.createTextNode(node.textContent);if(node.nodeType!==1)return document.createTextNode('');if(!allowed.has(node.tagName)){const f=document.createDocumentFragment();if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','TEMPLATE'].includes(node.tagName))return f;node.childNodes.forEach(n=>f.append(clean(n)));return f}const e=document.createElement(node.tagName.toLowerCase());if(node.tagName==='IMG'){if(!/^data:image\/(png|jpeg|webp);base64,[a-z\d+/=\s]+$/i.test(node.getAttribute('src')||''))return document.createTextNode('');e.src=node.getAttribute('src');e.alt=node.getAttribute('alt')||'';}if(node.tagName==='INPUT'){if(node.type!=='checkbox')return document.createTextNode('');e.type='checkbox';if(node.hasAttribute('checked'))e.setAttribute('checked','');e.setAttribute('aria-label',t('checklist'));}if(node.tagName==='A'){const href=node.getAttribute('href')||'';if(/^https?:\/\//i.test(href)){e.href=href;e.rel='noopener noreferrer';e.target='_blank';}}if(node.dir==='rtl'||node.dir==='ltr')e.dir=node.dir;node.childNodes.forEach(n=>e.append(clean(n)));return e}const out=document.createElement('div');doc.body.childNodes.forEach(n=>out.append(clean(n)));return out.innerHTML;}
function plain(html){const d=document.createElement('div');d.innerHTML=sanitize(html);return d.textContent||''}
const notes=()=>records.filter(r=>r.kind==='note'&&!r.deleted), folders=()=>records.filter(r=>r.kind==='folder'&&!r.deleted), getCurrent=()=>records.find(r=>r.id===current);
function brand(){return '<div class="brand"><img src="./assets/appnote-icon.jpg" alt=""><span>app ai</span><em>NOTES</em></div>'}
const btn=(action,label,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function authScreen(){return `<div class="welcome"><section class="welcome-art">${brand()}<span class="greeting">YOUR LITTLE SPACE</span><h1>${esc(t('authArt')).replace('\n','<br>')}</h1><p>${t('authArtSub')}</p><div class="mini-notes"><div class="mini-note">✦<strong>${t('noteSample')}</strong>${t('sampleLine')}<div class="mini-line"></div><div class="mini-line short"></div></div><div class="mini-note">☀<strong>${t('noteSample2')}</strong><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line short"></div></div></div><small>WRITE. THINK. MAKE IT YOURS.</small></section><section class="welcome-form"><div class="auth-box"><div class="auth-tools">${btn('language',prefs.lang==='ar'?'English':'العربية')}${btn('theme',prefs.theme==='dark'?'☀':'☾')}</div>${brand()}<h2>${t('welcome')}</h2><p class="subtitle">${t('authSub')}</p><div class="auth-tabs">${btn('auth-login',t('login'),authMode==='login'?'active':'')}${btn('auth-signup',t('signup'),authMode==='signup'?'active':'')}</div><form id="auth-form">${authMode==='signup'?`<label class="field">${t('username')}<input name="username" maxlength="30" required autocomplete="nickname"></label>`:''}<label class="field">${t('email')}<input name="email" type="email" dir="ltr" required autocomplete="email" placeholder="you@example.com"></label><label class="field">${t('password')}<input name="password" type="password" required ${authMode==='signup'?'minlength="6" maxlength="16"':''} autocomplete="${authMode==='signup'?'new-password':'current-password'}" placeholder="••••••••"></label><div id="auth-error" class="error-text" role="alert"></div><button class="primary" type="submit">${t(authMode==='signup'?'signup':'login')} ←</button></form>${btn('reset-password',t('resetPassword'))}<p class="hint">${t('authHint')}</p>${btn('guest',t('local'),'soft','style="width:100%;margin-top:8px"')}${btn('install','↓ '+t('install'),'','style="width:100%;margin-top:10px"')}<div class="auth-footer">${t('localHint')}<br>${t('noEmail')}</div></div></section></div>`;}
function navButton(v,label,icon,count){return btn('nav',`<span class="icon">${icon}</span>${label}${count!==undefined?`<span class="count">${count}</span>`:''}`,view===v?'active':'',`data-view="${v}"`)}
function sidebar(){return `<aside class="sidebar">${brand()}${btn('new-note','＋ '+t('newNote'),'primary')}${btn('upload-pdf','↑ '+t('uploadPDF'),'soft')}<nav class="nav">${navButton('notes',t('notes'),'▤',notes().length)}${navButton('folders',t('folders'),'▱',folders().length)}${navButton('fav',t('fav'),'☆',notes().filter(n=>n.data.favorite).length)}${navButton('chats',t('chats'),'◌')}${navButton('trash',t('trash'),'♲',records.filter(n=>n.deleted&&n.kind!=='folder').length)}</nav><section><div class="row spread nav-label"><span>${t('folders')}</span>${btn('new-folder','＋','','aria-label="'+t('newFolder')+'"')}</div><div class="nav">${folders().map(f=>`<div class="folder-row">${btn('folder',`<span>▱</span> ${esc(f.data.title)} <span class="count">${collectionNotes(records,f.id).length}</span>`,view==='folder'&&folder===f.id?'active':'',`data-id="${f.id}"`)}${btn('rename-folder','⋯','','data-id="'+f.id+'" aria-label="'+t('rename')+'"')}</div>`).join('')}</div></section><div class="sidebar-bottom">${btn('install','↓ '+t('install'),'soft')}<div class="nav">${navButton('settings',t('settings'),'⚙')}</div><div class="sync"><span class="dot"></span><span id="sync-status">${statusText()}</span></div><div class="account"><span class="avatar">${esc((session?.user.user_metadata?.username||'M')[0].toUpperCase())}</span><div><strong class="small">${esc(session?.user.user_metadata?.username||t('guest'))}</strong><div class="small muted">${session?'appnote cloud':t('localOnly')}</div></div>${btn('account',session?'↗':'→','','aria-label="'+t(session?'logout':'login')+'"')}</div></div></aside>`}
function statusText(){return !navigator.onLine?t('offline'):!session?t('localOnly'):t(syncState||'sync')}
function setStatus(s){syncState=s;const e=$('#sync-status');if(e)e.textContent=statusText()}
function topbar(){return `<header class="topbar"><div class="row">${btn('menu','☰','mobile-menu','aria-label="Menu"')}<span class="breadcrumb">${t('notes')} <span style="padding:0 12px">/</span> ${view==='editor'?esc(getCurrent()?.data.title||t('untitled')):t(view==='folder'?'folders':view==='chat'?'chats':view)}</span></div><label class="search"><span>⌕</span><input id="search" aria-label="${t('search')}" placeholder="${t('search')}" value="${esc(query)}"></label><div class="row top-actions">${btn('language',prefs.lang==='ar'?'EN':'عربي')}${btn('theme',prefs.theme==='dark'?'☀':'☾','','aria-label="'+t('theme')+'"')}</div></header>`}
function getChat(create=false){let c=records.find(r=>r.id===chatId&&!r.deleted);if(!c&&view==='editor')c=records.find(r=>r.kind==='chat'&&!r.deleted&&r.data.noteId===current);if(!c&&create){c=make('chat',{title:getCurrent()?.data.title||t('newChat'),messages:[],noteId:view==='editor'?current:null});chatId=c.id}return c;}
function messagesMarkup(){const c=getChat();return c?.data.messages?.length?c.data.messages.map((m,i)=>`<div class="message ${m.role==='user'?'user':m.error?'error':''}"><div class="message-content">${m.role==='model'&&!m.error?formatMathMessage(m.text):esc(m.text)}</div>${m.sources?.length?`<small>${t('sources')}: ${m.sources.map(s=>esc(s.title)).join(' · ')}</small>`:''}${m.sources?.some(s=>s.pdfId)?`<div class="pdf-source-links">${m.sources.filter(s=>s.pdfId).slice(0,14).map(s=>btn('pdf-source',s.page?t('pdfPage')+' '+s.page:t('pdfPages'),'soft',`data-note-id="${esc(s.pdfId)}" data-page="${s.page||1}"`)).join('')}</div>`:''}${m.role==='model'&&!m.error?`<div>${btn('copy-message',t('copy'),'','data-index="'+i+'"')}${view==='editor'?btn('append-message',t('append'),'','data-index="'+i+'"'):''}</div>`:''}</div>`).join(''):`<div class="chat-intro"><div class="spark">✧</div><strong>${t('chatIntro')}</strong><p>${localStorage.getItem('appnote-gemini-key')?t(view==='editor'?'includeCurrent':'newChatIntro'):t('chatHint')}</p>${btn('settings',t('settings'),'soft')}</div>`}
function aiPanel(){return `<section class="ai-panel"><header class="ai-head"><div class="row spread"><h3><span class="badge">AI</span> app ai</h3><div>${btn('new-chat','＋','','aria-label="'+t('newChat')+'"')}${getChat()?btn('trash',t('delete'),'danger','data-id="'+getChat().id+'" aria-label="'+t('deleteChat')+'"'):''}${btn('settings','⚙','','aria-label="'+t('settings')+'"')}</div></div>${view==='editor'?`<div class="ai-options">${['summarize','rewrite','translate','tasks'].map(a=>btn('quick-ai',t(a),'','data-prompt="'+a+'"')).join('')}</div>`:''}</header><label class="context-label"><input type="checkbox" id="memory" ${prefs.memory?'checked':''}>${t('memory')}</label>${view==='editor'?`<label class="context-label"><input type="checkbox" id="include-current" ${attachCurrent?'checked':''}>${t('currentContext')}</label>`:''}<div class="messages" id="messages" aria-live="polite">${messagesMarkup()}</div><form class="composer" id="chat-form"><textarea id="prompt" placeholder="${t('chatPlaceholder')}" aria-label="${t('chatPlaceholder')}" maxlength="20000" ${busy?'disabled':''}></textarea><p id="ai-progress" class="pdf-progress" role="status"></p><div class="row"><small>${t('aiFoot')}</small>${busy?btn('stop',t('stop'),'soft'):`<button class="primary" type="submit">${t('send')} ↑</button>`}</div></form></section>`}
function editorView(){const n=getCurrent();if(!n){view='notes';return listView()}return `<div class="heading-row" style="margin-bottom:20px"><div class="row">${btn('back','← '+t('back'))}<span id="saved" class="saved">${t('saved')}</span></div><div class="row">${btn('history','↶','','title="'+t('history')+'" aria-label="'+t('history')+'"')}${btn('export',t('export'))}${btn('toggle-ai','✧ AI',showAI?'soft':'')}</div></div><div class="editor-view ${showAI?'':'no-ai'}"><article class="paper"><div class="editor-meta"><select id="note-folder" aria-label="${t('folders')}"><option value="">${t('noFolder')}</option>${folders().map(f=>`<option value="${f.id}" ${n.data.folder===f.id?'selected':''}>${esc(f.data.title)}</option>`).join('')}</select><select id="note-color" aria-label="${t('color')}">${['plain','lavender','peach','green','blue'].map((c,i)=>`<option value="${c}" ${n.data.color===c?'selected':''}>${['◻','🟪','🟧','🟩','🟦'][i]}</option>`).join('')}</select><span class="status-right"></span>${btn('pin',n.data.pinned?'⌁':'♧','','data-id="'+n.id+'" title="'+t('pin')+'"')}${btn('favorite',n.data.favorite?'★':'☆','','data-id="'+n.id+'" title="'+t('favorite')+'"')}${btn('trash',t('delete'),'danger','data-id="'+n.id+'" aria-label="'+t('deleteNote')+'"')}</div><div class="toolbar" role="toolbar">${[['bold','<b>B</b>'],['italic','<i>I</i>'],['underline','<u>U</u>'],['strikeThrough','<s>S</s>'],['insertUnorderedList','☷'],['insertOrderedList','1.'],['formatBlock','H₂'],['undo','↶'],['redo','↷']].map(([cmd,label])=>btn('format',label,'',`data-command="${cmd}" aria-label="${cmd}"`)).join('')}${btn('checklist','☑ '+t('checklist'))}${btn('image','▧','','title="'+t('image')+'" aria-label="'+t('image')+'"')}${btn('upload-pdf','PDF','soft')}${btn('drawing','✎','','title="'+t('drawing')+'" aria-label="'+t('drawing')+'"')}</div><input id="note-title" class="note-title" maxlength="200" value="${esc(n.data.title)}" placeholder="${t('untitled')}" aria-label="${t('untitled')}">${pdfAttachmentMarkup(n)}<div id="editor" class="editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${t('write')}" data-placeholder="${t('write')}">${sanitize(n.data.html||'')}</div></article>${showAI?aiPanel():''}</div>`}
function selectionButtons(r){return selecting?btn('select-record',selected.has(r.id)?'✓':'○','selection-toggle',`data-id="${r.id}" aria-label="${t('selectItem')}: ${esc(r.data.title||t('untitled'))}" aria-pressed="${selected.has(r.id)}"`):'';}
function card(n){const f=folders().find(f=>f.id===n.data.folder);return `<article class="note-card ${selected.has(n.id)?'selected':''} ${selecting?'selectable':''}" tabindex="0" data-open="${n.id}" data-color="${esc(n.data.color||'plain')}" aria-label="${esc(n.data.title||t('untitled'))}">${selectionButtons(n)}<div class="card-category"><span>${n.data.pdf?'<b class="pdf-card-badge">PDF</b> ':''}${esc(f?.data.title||t(n.kind==='chat'?'chats':'noFolder'))}</span><span>${n.data.pinned?'⌁':''} ${n.data.favorite?'★':''}</span></div><h3>${esc(n.data.title||t('untitled'))}</h3><div class="preview">${esc(n.kind==='chat'?(n.data.messages||[]).at(-1)?.text||t('noMessages'):n.data.pdf?(n.data.pdf.preview||t('pdfScanned')):n.data.text||'✎')}</div><div class="card-footer"><span>${date(n.updated)}</span><div class="actions">${n.deleted?btn('restore','↶ '+t('restore'),'soft',`data-id="${n.id}"`):`${btn('favorite',n.data.favorite?'★':'☆','',`data-id="${n.id}" aria-label="${t('favorite')}"`)}${btn('move-note','▱','',`data-id="${n.id}" aria-label="${t('moveToFolder')}"`)}${btn('trash',t('delete'),'danger',`data-id="${n.id}" aria-label="${t('deleteNote')}"`)}`}</div></div></article>`;}
function filteredNotes(){let list=view==='trash'?records.filter(r=>r.deleted&&r.kind!=='folder'):notes().filter(n=>(view!=='fav'||n.data.favorite)&&(view!=='folder'||n.data.folder===folder));if(query.trim())list=list.filter(n=>(n.data.title+' '+(n.data.text||'')+' '+JSON.stringify(n.data.messages||[])).toLowerCase().includes(query.toLowerCase()));if(filter==='pinned')list=list.filter(n=>n.data.pinned);return list.sort((a,b)=>(filter==='recent'?0:Number(!!b.data.pinned)-Number(!!a.data.pinned))||b.updated-a.updated);}
function selectionBar(){return `<div class="selection-bar"><span>${selected.size} ${t('selectedItems')}</span>${btn('select-all',t('selectAll'),'soft')}${view!=='chats'?btn('bulk-move','▱ '+t('moveToFolder'),'soft',selected.size?'':'disabled'):''}${btn('bulk-trash',t('deleteSelected'),'danger',selected.size?'':'disabled')}${btn('toggle-select',t('cancel'))}</div>`;}
function listView(){const list=filteredNotes();visibleIds=list.filter(r=>!r.deleted).map(r=>r.id);const title=view==='notes'?t('title'):view==='folder'?folders().find(f=>f.id===folder)?.data.title:t(view);return `<div class="heading-row"><div><div class="greeting">${t('hello')}</div><h1 class="page-title">${esc(title)}</h1><p class="subtitle">${t(view==='trash'?'trashHint':view==='folder'?'folderHint':'sub')}</p></div><div class="heading-actions">${view==='folder'?btn('edit-folder-notes','＋ '+t('addExisting'),'soft',`data-id="${folder}"`):''}${btn('upload-pdf','↑ '+t('uploadPDF'),'soft')}${btn('new-note','＋ '+t('newNote'),'primary')}</div></div>${view==='notes'?`<div class="ai-banner"><span class="spark">✧</span><div><strong>${t('aiTitle')}</strong><p>${t('aiSub')}</p></div>${btn('new-chat',t('ask')+' ↗')}</div>`:''}${view==='folder'?`<div class="folder-tools">${btn('rename-folder',t('rename'),'soft',`data-id="${folder}"`)}${btn('export-folder','↓ '+t('exportFolder'),'soft',`data-id="${folder}"`)}</div>`:''}<div class="filters">${['all','recent','pinned'].map(f=>btn('filter',t(f),filter===f?'active':'',`data-filter="${f}"`)).join('')}<span class="status-right small muted">${list.length}</span>${view!=='trash'?btn('toggle-select',t(selecting?'cancel':'selectItems'),selecting?'soft':''):''}</div>${selecting?selectionBar():''}<div class="grid" id="notes-grid">${list.map(card).join('')}${view!=='trash'&&!selecting?`<button class="note-card new" data-action="new-note"><span>＋</span><strong>${t('newNote')}</strong></button>`:''}</div>${!list.length&&view==='trash'?`<div class="empty">${t('empty')}</div>`:''}<p class="footer-note">${t('shortcuts')}</p>`;}
function foldersView(){const list=folders().filter(f=>!query||f.data.title.toLowerCase().includes(query.toLowerCase()));return `<div class="heading-row"><div><div class="greeting">${t('organizedThoughts')}</div><h1 class="page-title">${t('foldersTitle')}</h1><p class="subtitle">${t('folderHint')}</p></div>${btn('new-folder','＋ '+t('newFolder'),'primary')}</div><div class="folder-grid">${list.map(f=>`<article class="folder-card"><button class="folder-open" data-action="folder" data-id="${f.id}"><span class="folder-symbol">▱</span><h2>${esc(f.data.title)}</h2><p>${collectionNotes(records,f.id).length} ${t('noteCount')}</p><div class="folder-preview">${collectionNotes(records,f.id).slice(0,3).map(n=>`<span>▤ ${esc(n.data.title||t('untitled'))}</span>`).join('')}</div></button><div class="folder-card-actions">${btn('edit-folder-notes',t('addExisting'),'soft',`data-id="${f.id}"`)}${btn('rename-folder',t('rename'),'',`data-id="${f.id}"`)}</div></article>`).join('')}<button class="folder-card new-folder" data-action="new-folder"><span>＋</span><strong>${t('newFolder')}</strong></button></div>`;}
function chatsView(){const chats=records.filter(r=>r.kind==='chat'&&!r.deleted&&(!query||JSON.stringify(r.data).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.updated-a.updated);visibleIds=chats.map(r=>r.id);return `<div class="heading-row"><div><div class="greeting">APP AI</div><h1 class="page-title">${t('chatTitle')}</h1><p class="subtitle">${t('chatsSub')}</p></div><div class="heading-actions">${btn('toggle-select',t(selecting?'cancel':'selectItems'),'soft')}${btn('new-chat','＋ '+t('newChat'),'primary')}</div></div>${selecting?selectionBar():''}<div class="chat-list">${chats.map(c=>`<div class="chat-item ${selected.has(c.id)?'selected':''}">${selectionButtons(c)}${btn('open-chat',`<span class="chat-symbol">◌</span><strong>${esc(c.data.title)}</strong><div class="small muted">${date(c.updated)} · ${c.data.messages?.length||0}</div>`,'',`data-id="${c.id}"`)}${btn('trash',t('delete'),'danger',`data-id="${c.id}" aria-label="${t('deleteChat')}"`)}</div>`).join('')}</div>${!chats.length?`<div class="empty">${t('empty')}</div>`:''}`;}
function showMoveDialog(ids){dialog(t('moveToFolder'),`<form id="move-form" data-ids="${ids.join(',')}" class="stack"><label class="field">${t('folders')}<select id="move-folder"><option value="">${t('noFolder')}</option>${folders().map(f=>`<option value="${f.id}">${esc(f.data.title)}</option>`).join('')}</select></label><button type="submit" class="primary">${t('move')}</button></form>`);}
function folderPicker(id){const f=folders().find(f=>f.id===id);if(!f)return;dialog(f.data.title,`<p class="hint">${t('chooseFolderNotes')}</p><form id="folder-notes-form" data-id="${id}"><div class="folder-note-picker">${notes().map(n=>`<label class="folder-pick-row"><input type="checkbox" name="note" value="${n.id}" ${n.data.folder===id?'checked':''}><span><strong>${esc(n.data.title||t('untitled'))}</strong><small>${esc(folders().find(f=>f.id===n.data.folder)?.data.title||t('noFolder'))}</small></span></label>`).join('')||`<p class="hint">${t('empty')}</p>`}</div><button type="submit" class="primary" style="width:100%;margin-top:18px">${t('save')}</button></form>`);}
function toggleSelected(id){if(selected.has(id))selected.delete(id);else selected.add(id);render();}
function clearSelection(){selecting=false;selected.clear();}
function handleCollectionAction(a,b){const id=b.dataset.id;
 if(['nav','folder','back','chats-back','new-note','new-chat'].includes(a))clearSelection();
 if(a==='toggle-select'){selecting=!selecting;selected.clear();render();return true}
 if(a==='select-record'){toggleSelected(id);return true}
 if(a==='open-chat'&&selecting){toggleSelected(id);return true}
 if(a==='select-all'){if(visibleIds.every(id=>selected.has(id)))selected.clear();else visibleIds.forEach(id=>selected.add(id));render();return true}
 if(a==='move-note'){showMoveDialog([id]);return true}
 if(a==='bulk-move'){showMoveDialog([...selected]);return true}
 if(a==='bulk-trash'){trashRecords(records,[...selected]).forEach(change);clearSelection();render();toast(t('movedToTrash'));return true}
 if(a==='edit-folder-notes'){folderPicker(id);return true}
 if(a==='export-folder'){const f=folders().find(f=>f.id===id);download('appnote-folder-'+(f?.data.title||'notes').replace(/[^\p{L}\p{N}_-]/gu,'_')+'.json',JSON.stringify(collectionBackup(records,id),null,2));return true}
 return false;
}
function handleCollectionSubmit(form){if(form.id==='move-form'){moveNotes(records,form.dataset.ids.split(','),$('#move-folder').value||null).forEach(change);clearSelection();$('#modal').close();render();toast(t('done'));return true}if(form.id==='folder-notes-form'){assignCollection(records,form.dataset.id,new FormData(form).getAll('note')).forEach(change);$('#modal').close();view='folder';folder=form.dataset.id;render();toast(t('done'));return true}return false;}

function render(){persistPrefs();if(loading){$('#app').innerHTML='<div class="empty">app ai ···</div>';return}if(!session&&!guest){$('#app').innerHTML=authScreen();return}$('#app').innerHTML=`<div class="shell">${sidebar()}<main class="main">${topbar()}${view==='folders'?foldersView():view==='editor'?editorView():view==='chats'?chatsView():view==='chat'?`<div class="chat-page"><div class="heading-row" style="margin-bottom:18px">${btn('chats-back','← '+t('chats'))}<strong>${esc(getChat()?.data.title||t('newChat'))}</strong></div>${aiPanel()}</div>`:listView()}</main></div>`;if($('#messages'))$('#messages').scrollTop=$('#messages').scrollHeight;bindEditor();updateInstallUI();renderMessageMath($('#messages'),prefs.lang);if(view==='editor'&&getCurrent()?.data.pdf)mountPdfPage(pdfPageNumbers.get(current)||1);else pdfRenderGeneration++;}
async function enter(){await saveChain.catch(()=>{});records=await storeGet(workspace());loading=false;current=null;chatId=null;view='notes';render();sync();pdfManager.resume(records).catch(()=>{});}
function dialog(title,body){$('#modal').innerHTML=`<div class="row spread"><h2>${esc(title)}</h2>${btn('close','×','','aria-label="'+t('close')+'"')}</div><div class="dialog-body">${body}</div>`;$('#modal').showModal();}
